import { Search, Calendar, User, Loader2, AlertCircle, Eye, Trash2, Pencil, X, Check } from "lucide-react";
import { getBookings, updateBooking, getRooms } from "@/services/api";
import type { Booking, Room } from "@/types/api";

export default function AdminBookingsPage() {
  const [bookings, setBookings] = useState<Booking[]>([]);
  const [rooms, setRooms] = useState<Room[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [searchQuery, setSearchQuery] = useState("");
  const [activeFilter, setActiveFilter] = useState("Ham─▒s─▒");

  // Edit Modal State
  const [editBookingId, setEditBookingId] = useState<string | null>(null);
  const [editForm, setEditForm] = useState<Partial<Booking>>({});

  const loadData = async () => {
    try {
      setLoading(true);
      const [bookingsData, roomsData] = await Promise.all([
        getBookings(),
        getRooms()
      ]);
      setBookings(bookingsData);
      setRooms(roomsData);
    } catch (err: unknown) {
      setError(err.message || "X╔Öta ba┼ƒ verdi");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    // eslint-disable-next-line react-hooks/set-state-in-effect
    // eslint-disable-next-line react-hooks/exhaustive-deps
    loadData();
  }, []);

  const handleToggleStatus = async (id: string, currentStatus: string) => {
    const statuses = ["pending", "confirmed", "cancelled"] as const;
    const next = statuses[(statuses.indexOf(currentStatus as unknown) + 1) % statuses.length];
    
    // Optimistic update
    setBookings((prev) => prev.map((b) => (b._id === id ? { ...b, status: next } : b)));
    
    try {
      await updateBooking(id, { status: next });
      loadData();
